pub(super) fn verify(
    value: &Value,
    runtime_schema: &str,
    package_graph: Option<&VerifiedPackageGraph>,
    os_support_executable_cid: Option<&str>,
) -> Result<()> {
    let schema_matches_graph = package_graph.is_some_and(|graph| {
        (runtime_schema == RUNTIME_SCHEMA_V5 && graph.schema == PACKAGE_GRAPH_SCHEMA_V2)
            || (runtime_schema == RUNTIME_SCHEMA_V6 && graph.schema == PACKAGE_GRAPH_SCHEMA_V3)
