                && graph.schema != PACKAGE_GRAPH_SCHEMA_V3)
                && graph.schema != PACKAGE_GRAPH_SCHEMA_V4)
    });
    if !schema_matches_graph {
        bail!("foreign-process Node runtime schema does not match package materialization");
    }
