            facts
                .nodes
                .iter()
                .map(|node| {
                    (
                        node.name.as_str(),
                        node.version.as_str(),
                        node.main.as_str(),
                    )
                })
                .collect()
        })
    }

    pub(super) fn dag_edges(&self) -> Option<&[(String, String)]> {
        self.dag.as_ref().map(|facts| facts.edges.as_slice())
