//! Runtime scalar aliases are separate from the frozen model wire recipe.
//! Catalog identity and prompt schemas remain unchanged by validation views.
use std::collections::BTreeMap;

use serde_json::Value;

use super::{protocol, ResolverError, MAX_REQUEST_BYTES};
use crate::hotpath::schema::InputSpec;

pub(super) fn validate(
    inputs: &BTreeMap<String, InputSpec>,
    arguments: &BTreeMap<String, Value>,
) -> Result<(), ResolverError> {
    if !inputs.values().any(|spec| spec.type_name == "path") {
        return protocol::validate_arguments(inputs, arguments);
    }
    // Only the bounded validation view changes. Never coerce, normalize,
    // expand or open a path; an admitted string is not filesystem authority.
    let mut scalars = inputs.clone();
    for (name, spec) in &mut scalars {
        if spec.type_name == "path" {
            if arguments.get(name).is_some_and(|value| {
                !value.as_str().is_some_and(|path| {
                    !path.is_empty() && path.len() <= MAX_REQUEST_BYTES && !path.contains('\0')
                })
            }) {
                return Err(ResolverError::InvalidArguments);
            }
            spec.type_name = "string".into();
        }
    }
    // Original unknown-field, required/default and constraint checks still run.
    protocol::validate_arguments(&scalars, arguments)
}
"}
