    cmd: "rg -n -i -g '*.rs' -g '*.toml' -g '*.json' -g '*.nl' -g '*.newlanguage' -g '!target/**' \"hotpath\\.explicit-mp4-h264|first[-_ ]sync|bounded[-_ ]multi[-_ ]frame|contact[-_ ]sheet|keyframe[-_ ]timestamps?|video[-_ ]timeline\" .",
    workdir: item.path,
    yield_time_ms: 10000,
    max_output_tokens: 20000
  });
  text(JSON.stringify({label:item.label, exit_code:r.exit_code, output:r.output}));
}
